contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(beforeOwner == address(this));

        c.owned(); if (__ESBMC_reverted()) return;

        assert(c.owner() == beforeOwner && c.owner() == address(this));
    }

    receive() external payable {}
}

